"""Apply the project history documentation after existing manual revisions."""
from pathlib import Path
import base64

SECTION = '''<h3 id="project-history">プロジェクト履歴：依頼・作業・判断をたどる</h3>
<p><b>目的：</b>プロジェクトに対する新規依頼や台帳からの依頼をまとめ、いつ、どのAIが、どの工程を行ったかを確認します。改修相談から作業・レビューへ進んだ経緯を共有するための画面です。</p>
<p><b>IMPLEMENTED：</b>画面上部のタブ「プロジェクト履歴」から開きます。画面のURLは <code>/history</code> です。2026-10-03のUI改善で、左に依頼の一覧、右に選んだ依頼の詳細を表示する2列の画面になりました。開いた時点で最新の依頼を選びます。</p>
<ol><li>「対象プロジェクト」で対象を選びます。選択欄と依頼の一覧に表示する名称は、台帳の基本情報に保存された「プロジェクト名」を表示します。台帳未登録の場合はフォルダ名を表示します。同じ名前でもパスが異なるプロジェクトは別に扱います。</li>
<li>必要に応じて「依頼の入口」や依頼名で絞り込みます。一覧の各依頼には、状態（記号と名前）・依頼の入口・プロジェクト名・受付日時・工程数を表示します。依頼を押すと右側に詳細を表示します。資料作成の依頼は保存先と読み取り元の両方から検索できます。</li>
<li>詳細の上部の集計で、工程数・実行時間の合計・再試行の回数・確認と承認の件数を確認します。「① 工程の時系列」では、時刻の目盛り（日をまたぐ場合は日付付き）に沿った横棒と状態名で、待機・実行・確認待ち・停止などを確認します。各工程にはAIの担当・モデル、試行回数、開始〜終了、実行時間、取得済みトークンを表示します。短い横棒では状態名を棒の外に表示します。</li>
<li>「②③ 承認の記録と作業の動き」では、確認・承認（種類・結果・日時・メモ）と作業イベントを1本の時系列にまとめて新しい順に表示します。「確認・承認／工程の進行／再試行・停止／その他」のチェックで表示する種類を絞り込めます。イベントは200件ずつ取得し、「過去の記録をさらに表示」で続きを読みます。消費トークンと利用枠は詳細下部の折りたたみで確認します。</li>
<li>最新の状態は「最新の状態に更新」で取得します。自動更新はありません。再開・修正依頼・承認などの操作は作業ボードで行います。状態名はすべて日本語で表示します（例：成果受け入れ済み）。</li></ol>
<div class="table-wrap"><table><thead><tr><th>表示</th><th>意味・制限</th></tr></thead><tbody>
<tr><td>台帳からの依頼</td><td>保存された相談記録と依頼IDの結び付きを確認できる依頼です。</td></tr>
<tr><td>新規依頼／入口未記録</td><td>履歴機能追加後に直接作成された依頼は「新規依頼」。過去の入口が未保存の場合は「入口未記録」とし、新規依頼と推定しません。</td></tr>
<tr><td>開始・終了・実行時間</td><td>保存された最新試行の工程時刻を使用します。実行時間は開始から終了までの経過時間で、モデル推論だけの時間ではありません。実行中は画面更新時点の経過時間です。記録がなければ「未記録」。全試行の累計時間は表示しません。</td></tr>
<tr><td>担当工程終了</td><td>工程の処理終了です。依頼全体の成果受け入れや実機検証済みを意味しません。承認記録と作業ボードも確認してください。</td></tr>
<tr><td>トークン・利用枠</td><td>詳細下部で、工程・依頼の入力、キャッシュ読取・作成、出力トークンを確認します。修正・再試行・レビューを含む取得済み分の合計です。保持範囲は最大31試行分で、未取得を0としません。依頼前の台帳相談は含みません。CLIごとに入力とキャッシュの定義が異なるため単純加算しません。利用枠は最新取得値と最新試行の開始前・終了後の取得値を表示します。古い値を明示し、前後が同じ取得時刻なら消費を示しません。他の作業も影響するため依頼単独の消費量や課金額には換算しません。</td></tr>
<tr><td>人の担当</td><td>依頼者・進捗確認者・成果確認者・承認者の本人確認は未実装で「未記録」です。AIの担当表示から人の担当を推測しません。</td></tr>
</tbody></table></div>
<p><b>安全・共有：</b>読み取り専用の画面で、追加のAI呼び出しや外部送信は行いません。パス・依頼名・承認理由・作業記録を含むため、画面共有やスクリーンショットの公開前に内容を確認してください。既存のローカル画面認証を使用しており、チーム利用の個人ログインや人物別の閲覧権限は未実装です。</p>
<p><b>残る課題：</b>利用者ログイン、依頼者・確認者・承認者の役割記録、個人のAIライセンスによる分散実行、全試行の時間集計は今後の検討対象です。削除済みの履歴や未記録の操作は復元しません。構文・稼働版のページとAPI応答を確認しています。2026-10-03のUI改善では隔離したサンプル画面の依頼切り替え・絞り込み、本番の表示と狭い画面幅を確認済みです。本番の手動操作、スマホ実機、通知の実際の鳴動はNOT TESTEDです。</p>
'''
SECTION += '<div id="image-attachment-manual"><h4>参考ファイルを使って依頼・相談する</h4><p>新規依頼・台帳相談の「参考ファイルを添付」で、PNG/JPEG/WebP、PDF、DOCX/XLSX/PPTX、テキスト・CSV・Markdown・ログ・設定・ソースコードを選びます。画像の貼り付けも可能です。4ファイル、各5MB・合計15MBまで。画像はプレビューでき、送信前は「取り消す」で外せます。</p><p>送信時にローカルで全文抽出・画像OCRを検査し、上位指示の無視、権限や承認の偽装、秘密情報の取得・送信などを疑う場合は拒否します。検査できない形式、暗号化、破損、処理上限、OCRや解析環境の不足も拒否します。マクロ・実行ファイル・一般ZIPは許可しません。攻撃例を説明している正当な資料も拒否される場合があります。疑わしい指示を除いて添付し直してください。</p><p>PDFは20ページ、検査OCR領域は40以内、抽出内容は添付セット全体15万文字以内です。検査には時間がかかる場合があります。検査通過は完全な安全保証ではありません。既存の作業範囲・承認条件は変えません。</p><p>画像はメタデータを除いて正規化し、文書は抽出文字としてAIへ渡します。文書の図表・レイアウト・計算結果は再現しません。原本は実行しません。相談で受け付けた添付は依頼と後続担当へ引き継ぎ、古い添付も再利用前に検査します。再試行は前の添付を使い、新しい添付は「相談を送る」で追加します。</p><p>拒否された資料は永続保存・AI送信しません。許可した原本と検査結果はPCに履歴として保存します。送信前に個人情報・認証情報を除いてください。保存容量は全体512MB、削除画面と個人別閲覧権限は未実装です。実ファイルの拒否・OCR・AIによる作業の一巡は未確認です。</p></div>'
SECTION += '<div id="instruction-size-manual"><h4>指示ファイルが大きくなったときの警告</h4><p>台帳でプロジェクトの詳細を開くと、指示ファイルの容量を読み取り専用で確認します。「容量を再確認」で最新のサイズを調べます。「ファイル別の容量・行数と確認範囲」を開くと、各ファイルのKiB・bytes・行数を確認できます。台帳の再調査時には開始フォルダまでの情報を記録し、詳細では子フォルダも限定して調べます。一覧の警告は確認時点の情報です。</p><p>Codexの指示読み込みは既定で合計32 KiBです。AGENTS.override.mdの優先や階層の合計候補、利用者の共通指示も考慮し、80%以上で注意、上限到達・超過で末尾や後続の指示が省略される可能性を警告します。実行時の設定・信頼状態は完全には再現しないため、上限と合計は候補です。</p><p>Claude CodeはCLAUDE.mdを200行未満にすることが公式の推奨です。200行以上は肥大化の注意で、200行で打ち切られる意味ではありません。長い1行の対策として、采来では32 KiB以上でも注意しますが、これはClaude Codeの公式上限ではありません。現在の公式仕様では4 MiB超のCLAUDE.mdは読み込み対象外です。AGENTS.mdの直接対応は版と設定に依存します。MEMORY.mdの200行・25 KB制限とは区別します。</p><p>新規依頼では対象を選んだ時点、ハーネス調査では調査結果に警告を表示します。台帳相談から作成した依頼も、依頼作成時の診断を作業カードに残します。古い依頼の記録は捏造せず、確認中・未確認・範囲の打ち切りを表示します。警告は作業停止や承認ではありません。</p><p>必須の規則を先頭に残し、詳細を別資料・必要時に読むSkill・対象を限定したルールへ移します。参照するだけでは必ず読み込まれる保証はなく、Claudeの@importは整理には使えても読み込み量を減らす保証にはなりません。ファイルの自動短縮、上限や権限の変更はしません。常時監視ではありません。実画面の操作・AIが実際に読んだ範囲は未確認です。</p></div>'
SECTION += '<div id="instruction-presence-manual"><h4>指示ファイルの不足で台帳を絞り込む</h4><p>台帳の「指示ファイル」フィルタで「どちらか不足」「両方なし」「AGENTS.md系なし」「CLAUDE.md系なし」「両方あり」「未確認」を選びます。名前・パス・目的の検索、分類、アーカイブ・削除の表示と組み合わせられます。フィルタは表示の絞り込みだけで、AI作業の許可やデータは変更しません。</p><p>不足するプロジェクトは一覧に警告を表示します。台帳を表示・再読み込みした時点でファイル名の存在を確認し、古い台帳の再調査を必須にしません。詳細の「容量を再確認」でも更新できます。フォルダ不在、リンク・権限等、家庭関連は「未確認」とし、「両方なし」に含めません。</p><p>判定はプロジェクト直下です。AGENTS.mdとAGENTS.override.mdのいずれか、CLAUDE.md・.claude/CLAUDE.md・CLAUDE.local.mdのいずれかがあれば、それぞれ「あり」です。agent.mdという単数形は標準名として数えません。親や利用者共通の指示、Codexの代替名、Claudeのインポート、実際にAIが読んだ範囲は別途確認します。ファイルの存在は内容の適切さを保証しません。自動生成・編集・実行停止は行いません。</p></div>'
SECTION += '<div id="instruction-convert-manual"><h4>指示ファイルがないときはコンバートで作成する</h4><ol><li>台帳の基本情報に目的・制約・検証方法を記入して保存します。</li><li>ハーネス化の読み取り専用調査で作成案を生成し、AGENTS.md・CLAUDE.mdと関連資料の内容を確認します。</li><li>指示ファイルの作成だけが目的なら、ファイル移動案は空にします。作成先と対象ファイルを確認してチェックし、「確認したコンバートを実行」を押します。</li><li>既存ファイルは上書きしません。不明な情報はUNKNOWNとして残るため、作成後に確認・補完します。</li><li>台帳を再読み込みし、指示ファイルの不足警告が解消したか確認します。容量の警告は「容量を再確認」で更新します。</li></ol><p>台帳登録だけでは指示ファイルを作成しません。生成したルーターや資料は出発点であり、プロジェクトの十分な調査やAIの読み込みを保証するものではありません。</p></div>'
SECTION += """<div id="decision-wait-manual"><h4>人の判断待ち時間と試行別トークン</h4><p>履歴の「人の判断待ちの集計」を開き、開始日・終了日（日本時間）を指定して集計します。平日9:00〜18:00が初期設定です。種類別の区間数・中央値・90パーセンタイル・最大値は勤務時間内だけを計上し、時間外と再起動によるシステム停止を別表示します。導入前の依頼は「計測開始前」です。過去の時間は復元しません。</p><p>依頼の詳細と時系列に、判断待ちの種類・開始・終了・継続中の表示を追加しました。勤務時間内は塗りつぶし、時間外は斜線で表示します。同じ依頼で重なった待ちは二重に数えません。これは計測だけで、判断の期限・承認・再開条件を変えません。</p><p>「消費トークンと利用枠」に試行別の担当サービス・モデル・状態・取得済み利用量を表示します。古い試行のモデルが保存されていない場合は「モデル未記録」です。未取得をゼロや費用に置き換えません。</p><h4>停止した依頼の判断と台帳のタブ</h4><p>作業ボードの判断通知からカードを開き、停止理由・判断材料・次の操作を確認します。修正上限では範囲を指定して修正を依頼、失敗では原因確認や補足入力へ進めます。保留して閉じると停止状態は維持されます。AIの意見は承認とは区別します。</p><p>台帳詳細は「基本情報」「実行・検証」「ハーネス」「調査・関連」「管理操作」で切り替えます。分類は基本情報で編集し、「台帳に保存」を押します。タブ切替だけでは未保存入力は消えません。フォルダ移動・削除の確認手順は従来どおりです。</p><h4>勤務時間内の常駐PC通知</h4><p>作業ボード右上の「⋯」から「常駐PC通知を有効にする（勤務時間内）」を選びます。初期状態は無効です。「常駐PC通知を試す」でWindowsへのテスト送信ができます。判断待ち・成果確認・成果受領を件数のみで通知し、依頼名やパスは通知本文に含めません。時間外は保留し、次の勤務開始後（既定9:00）にまとめて通知します。休日は次の勤務日です。解消済みの判断待ちは通知しません。</p><p>常駐サービスとWindowsへのログインが必要です。ブラウザーを閉じても常駐通知は動きますが、サインアウトした端末への表示は保証しません。非対応・失敗時は画面内の通知を利用できます。外部サービスへの通知は接続先・送信範囲が未設定のため未実装です。</p></div>"""



def apply(path):
    source = path.read_text(encoding='utf-8')
    if 'id="project-history"' in source:
        begin = source.index('<h3 id="project-history">')
        finish = source.index('</section>', begin)
        source = source[:begin] + source[finish:]
    start = source.index('<section id="ledger">')
    end = source.index('</section>', start)
    figures = '<h4>画面で確認できる履歴（説明用サンプル）</h4><p>以下は実際の履歴画面を、実業務の情報を含まないサンプルデータで撮影したものです。表示時刻や承認結果は説明用であり、実運用の検証結果ではありません。</p>'
    for filename, caption in (
        ('16-history-projects.jpg', '① 依頼の一覧と詳細の2列。左で依頼を選び、右で状態・入口・集計を確認します。'),
        ('17-history-timeline.jpg', '② 工程の時系列。時刻の目盛りに沿って、計画・実装・レビューのAI担当、開始〜終了と実行時間を確認できます。'),
        ('18-history-details.jpg', '③ 承認の記録と作業の動き。計画承認と成果受け入れの日時・メモ、依頼作成から完了までのイベントを種類で絞り込んでたどれます。人の担当者は未記録です。')):
        encoded = base64.b64encode((path.parent / 'assets' / filename).read_bytes()).decode()
        figures += f'<figure><a href="data:image/jpeg;base64,{encoded}" target="_blank" rel="noopener"><img src="data:image/jpeg;base64,{encoded}" alt="{caption}" loading="lazy"></a><figcaption>{caption}（サンプルデータ）</figcaption></figure>'
    source = source[:end] + SECTION + figures + source[end:]
    needle = '<section id="sources"><h2>付録G 改訂履歴・参照資料</h2>'
    assert source.count(needle) == 1
    if '<p>2026-10-03：プロジェクト履歴の操作説明を追加。' not in source:
        source = source.replace(needle, needle + '<p>2026-10-03：プロジェクト履歴の操作説明を追加。プロジェクト名による折りたたみ、依頼の入口、工程の時刻・経過時間、承認・イベントの確認方法と未実装事項を記載しました。</p>', 1)
    revision = '<p>2026-10-04：人の判断待ち時間（勤務時間内・時間外・システム停止）、試行別トークン、停止理由から操作への案内、台帳詳細の5タブ、勤務時間内の常駐PC通知を追加。通知は初期無効です。実モデルによる完了一巡、OS通知の実表示・音声、スマホ実機は未確認です。</p>'
    if revision not in source:
        source = source.replace(needle, needle + revision, 1)
    path.write_text(source, encoding='utf-8')


if __name__ == '__main__':
    for name in ('index.html', 'agent-team-manual.html'):
        apply(Path(__file__).with_name(name))
